-- Migration initiale reproductible. Les types et tables suivent packages/database/prisma/schema.prisma.
CREATE TYPE "Role" AS ENUM ('ADMIN','EDITOR','VIEWER');
CREATE TYPE "IntegrationKind" AS ENUM ('WORDPRESS','ANTHROPIC','OPENAI','SSH');
CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT','ACTIVE','PAUSED','COMPLETED','FAILED','CANCELLED');
CREATE TYPE "WorkflowState" AS ENUM ('INTAKE','WORDPRESS_SNAPSHOT','SPECIFICATION_BY_CLAUDE','TECHNICAL_PLAN_BY_CODEX','PLAN_REVIEW_BY_CLAUDE','WAITING_FOR_PLAN_APPROVAL','IMPLEMENTATION_BY_CODEX','AUTOMATED_TESTS','REVIEW_BY_CLAUDE','FIXES_BY_CODEX','WAITING_FOR_DEPLOYMENT_APPROVAL','STAGING_DEPLOYMENT','STAGING_VALIDATION','PRODUCTION_DEPLOYMENT','COMPLETED','FAILED','CANCELLED');
CREATE TYPE "AgentName" AS ENUM ('user','claude','codex','system');
CREATE TYPE "AgentRecipient" AS ENUM ('user','claude','codex','system','all');
CREATE TYPE "AgentMessageType" AS ENUM ('brief','question','answer','specification','plan','review','decision','task','tool_call','tool_result','artifact','error');
CREATE TYPE "TaskStatus" AS ENUM ('PENDING','RUNNING','PASSED','FAILED','BLOCKED','CANCELLED');
CREATE TYPE "ArtifactKind" AS ENUM ('THEME','PLUGIN','CONTENT','REPORT','SNAPSHOT','DIFF','SCREENSHOT','ZIP','LOG');
CREATE TYPE "ApprovalKind" AS ENUM ('PLAN','DEPLOYMENT','ROLLBACK','DESTRUCTIVE');
CREATE TYPE "ApprovalStatus" AS ENUM ('PENDING','APPROVED','REJECTED','EXPIRED','CANCELLED');
CREATE TYPE "DeploymentTarget" AS ENUM ('LOCAL','REMOTE_CONTENT','REMOTE_SSH');
CREATE TYPE "DeploymentStatus" AS ENUM ('PLANNED','WAITING_APPROVAL','RUNNING','SUCCEEDED','FAILED','PARTIAL','ROLLED_BACK');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMPTZ,"version" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "Workspace" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMPTZ,"version" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "WorkspaceMember" ("workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" "Role" NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("workspaceId","userId"));
CREATE TABLE "IntegrationSecret" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"kind" "IntegrationKind" NOT NULL,"label" TEXT NOT NULL,"encryptedValue" TEXT NOT NULL,"iv" TEXT NOT NULL,"authTag" TEXT NOT NULL,"keyVersion" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"revokedAt" TIMESTAMPTZ,UNIQUE("workspaceId","kind","label"));
CREATE TABLE "WordPressSite" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"secretId" TEXT REFERENCES "IntegrationSecret"("id") ON DELETE SET NULL,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"isLocal" BOOLEAN NOT NULL DEFAULT FALSE,"allowPrivateNetwork" BOOLEAN NOT NULL DEFAULT FALSE,"lastConnectionStatus" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMPTZ,"version" INTEGER NOT NULL DEFAULT 1,UNIQUE("workspaceId","url"));
CREATE TABLE "WordPressSnapshot" ("id" TEXT PRIMARY KEY,"wordpressSiteId" TEXT NOT NULL REFERENCES "WordPressSite"("id") ON DELETE CASCADE,"payload" JSONB NOT NULL,"checksum" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"wordpressSiteId" TEXT REFERENCES "WordPressSite"("id") ON DELETE SET NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT',"brief" JSONB NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMPTZ,"version" INTEGER NOT NULL DEFAULT 1,UNIQUE("workspaceId","slug"));
CREATE TABLE "ProjectMemory" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL UNIQUE REFERENCES "Project"("id") ON DELETE CASCADE,"currentBrief" JSONB NOT NULL,"currentSpec" JSONB,"decisions" JSONB NOT NULL DEFAULT '[]',"siteMap" JSONB,"designTokens" JSONB,"taskState" JSONB NOT NULL DEFAULT '[]',"openIssues" JSONB NOT NULL DEFAULT '[]',"testReport" JSONB,"deploymentHistory" JSONB NOT NULL DEFAULT '[]',"compactSummary" TEXT NOT NULL DEFAULT '',"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"version" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "AgentRun" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"state" "WorkflowState" NOT NULL DEFAULT 'INTAKE',"stateVersion" INTEGER NOT NULL DEFAULT 1,"isPaused" BOOLEAN NOT NULL DEFAULT FALSE,"cancellationRequested" BOOLEAN NOT NULL DEFAULT FALSE,"currentAgent" "AgentName","turnCount" INTEGER NOT NULL DEFAULT 0,"fixCycleCount" INTEGER NOT NULL DEFAULT 0,"maxTurns" INTEGER NOT NULL DEFAULT 12,"maxFixCycles" INTEGER NOT NULL DEFAULT 2,"budgetCents" INTEGER,"consumedCents" INTEGER NOT NULL DEFAULT 0,"startedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"finishedAt" TIMESTAMPTZ,"lastError" JSONB,"idempotencyKey" TEXT NOT NULL,UNIQUE("projectId","idempotencyKey"));
CREATE TABLE "AgentMessage" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"runId" TEXT NOT NULL REFERENCES "AgentRun"("id") ON DELETE CASCADE,"sender" "AgentName" NOT NULL,"recipient" "AgentRecipient" NOT NULL,"type" "AgentMessageType" NOT NULL,"content" TEXT NOT NULL,"structuredPayload" JSONB NOT NULL,"artifactRefs" JSONB NOT NULL DEFAULT '[]',"parentMessageId" TEXT REFERENCES "AgentMessage"("id") ON DELETE SET NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AgentUsage" ("id" TEXT PRIMARY KEY,"runId" TEXT NOT NULL REFERENCES "AgentRun"("id") ON DELETE CASCADE,"agentName" "AgentName" NOT NULL,"model" TEXT,"inputTokens" INTEGER,"outputTokens" INTEGER,"estimatedCostCents" INTEGER,"durationMs" INTEGER NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"runId" TEXT REFERENCES "AgentRun"("id") ON DELETE SET NULL,"externalId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "TaskStatus" NOT NULL DEFAULT 'PENDING',"dependencies" JSONB NOT NULL DEFAULT '[]',"result" JSONB,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"version" INTEGER NOT NULL DEFAULT 1,UNIQUE("projectId","externalId"));
CREATE TABLE "Artifact" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"runId" TEXT REFERENCES "AgentRun"("id") ON DELETE SET NULL,"kind" "ArtifactKind" NOT NULL,"name" TEXT NOT NULL,"storagePath" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sha256" TEXT NOT NULL,"size" BIGINT NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("projectId","sha256","name"));
CREATE TABLE "Approval" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"runId" TEXT REFERENCES "AgentRun"("id") ON DELETE SET NULL,"kind" "ApprovalKind" NOT NULL,"status" "ApprovalStatus" NOT NULL DEFAULT 'PENDING',"summary" TEXT NOT NULL,"changes" JSONB NOT NULL,"decidedById" TEXT REFERENCES "User"("id") ON DELETE SET NULL,"comment" TEXT,"requestedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"decidedAt" TIMESTAMPTZ,"expiresAt" TIMESTAMPTZ,"version" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "Deployment" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"runId" TEXT REFERENCES "AgentRun"("id") ON DELETE SET NULL,"wordpressSiteId" TEXT NOT NULL REFERENCES "WordPressSite"("id") ON DELETE RESTRICT,"target" "DeploymentTarget" NOT NULL,"status" "DeploymentStatus" NOT NULL DEFAULT 'PLANNED',"plan" JSONB NOT NULL,"exactResponses" JSONB NOT NULL DEFAULT '[]',"backupArtifactId" TEXT,"idempotencyKey" TEXT NOT NULL,"startedAt" TIMESTAMPTZ,"finishedAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"version" INTEGER NOT NULL DEFAULT 1,UNIQUE("projectId","idempotencyKey"));
CREATE TABLE "DeploymentChange" ("id" TEXT PRIMARY KEY,"deploymentId" TEXT NOT NULL REFERENCES "Deployment"("id") ON DELETE CASCADE,"operation" TEXT NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT,"before" JSONB,"after" JSONB,"apiResponse" JSONB,"rollbackData" JSONB,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"projectId" TEXT REFERENCES "Project"("id") ON DELETE SET NULL,"runId" TEXT REFERENCES "AgentRun"("id") ON DELETE SET NULL,"actorType" TEXT NOT NULL,"actorId" TEXT,"action" TEXT NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT,"correlationId" TEXT NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "JobLock" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL UNIQUE REFERENCES "Project"("id") ON DELETE CASCADE,"ownerId" TEXT NOT NULL,"acquiredAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ NOT NULL,"heartbeatAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AgentMessage_project_created_idx" ON "AgentMessage"("projectId","createdAt");
CREATE INDEX "AgentRun_project_state_idx" ON "AgentRun"("projectId","state","isPaused");
CREATE INDEX "Approval_project_status_idx" ON "Approval"("projectId","status","requestedAt");
CREATE INDEX "AuditLog_workspace_created_idx" ON "AuditLog"("workspaceId","createdAt");
CREATE INDEX "JobLock_expires_idx" ON "JobLock"("expiresAt");
